const isPrime = (n) => {
  if (n < 2) return false;
  for (let d = 2; d * d <= n; d++) if (n % d === 0) return false;
  return true;
};
let hits = 0;
let total = 0;
for (let a = 1; a <= 6; a++) {
  for (let b = 1; b <= 6; b++) {
    total++;
    if (isPrime(a + b)) hits++;
  }
}
const gcd = (x, y) => (y === 0 ? x : gcd(y, x % y));
const g = gcd(hits, total);
return hits / g + total / g;
